/* Intro only for signed-out visitors; existing auth and Supabase remain untouched. */
(()=>{'use strict';const key='buchee_aurora_intro_seen_v1';const slides=[{icon:'✦',title:'Yeni bir dünya. Senin hikâyen.',text:'Paylaş, keşfet ve senin gibi düşünen insanlarla bağlantı kur.'},{icon:'▧',title:'Fikirleri keşfet.',text:'Gönderiler, hikâyeler ve videolarla yeni bakış açıları bul.'},{icon:'◎',title:'Kendi topluluğunu bul.',text:'İlgini çeken konuları takip et ve Buchee’de kendine yer aç.'}];let step=0,shown=false;const root=document.createElement('section');root.id='buchee-aurora-intro';root.hidden=true;root.setAttribute('aria-label','Buchee tanıtımı');root.setAttribute('role','dialog');root.setAttribute('aria-modal','true');function render(){const s=slides[step];root.innerHTML='<div class="buchee-aurora-panel"><button type="button" class="buchee-aurora-skip" data-intro="skip">Atla</button><div class="buchee-aurora-brand"><span class="buchee-aurora-mark">◉</span>Buchee</div><div><div class="buchee-aurora-visual"><span>'+s.icon+'</span></div><h1>'+s.title+'</h1><p>'+s.text+'</p></div><div class="buchee-aurora-bottom"><div class="buchee-aurora-dots">'+slides.map((_,i)=>'<i class="'+(i===step?'active':'')+'"></i>').join('')+'</div><button type="button" class="buchee-aurora-primary" data-intro="next">'+(step===slides.length-1?'Kayıt ol':'Devam et →')+'</button><button type="button" class="buchee-aurora-secondary" data-intro="login">Hesabım var, giriş yap</button></div></div>'}function close(mode){root.hidden=true;document.body.style.removeProperty('overflow');try{localStorage.setItem(key,'1')}catch{}if(mode){const b=document.querySelector('#auth-root [data-auth="'+mode+'"]');if(b)b.click()}}root.addEventListener('click',e=>{const a=e.target.closest('[data-intro]');if(!a)return;const v=a.dataset.intro;if(v==='next'&&step<slides.length-1){step++;render()}else close(v==='login'?'login':v==='next'?'signup':null)});function check(){if(shown||!root.hidden)return;const auth=document.getElementById('auth-root'),app=document.getElementById('app-root');if(!auth||!app||auth.classList.contains('hidden')||!app.classList.contains('hidden')||!auth.querySelector('#auth-form'))return;let seen=false;try{seen=localStorage.getItem(key)==='1'}catch{}if(seen)return;shown=true;step=0;render();root.hidden=false;document.body.style.overflow='hidden'}function init(){document.body.append(root);const auth=document.getElementById('auth-root');if(auth){new MutationObserver(()=>{if(!root.hidden&&auth.classList.contains('hidden'))close();else check()}).observe(auth,{attributes:true,attributeFilter:['class'],childList:true,subtree:false})}check();setTimeout(check,600);setTimeout(check,1800)}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init()})();